type MarkOutboxFailedParams struct {
	LastError *string
	EventID   uuid.UUID
}

func (q *Queries) MarkOutboxFailed(ctx context.Context, arg MarkOutboxFailedParams) error {
	_, err := q.db.Exec(ctx, markOutboxFailed, arg.LastError, arg.EventID)
	return err
}

