const updatePayment = `-- name: UpdatePayment :execrows
UPDATE app.payments
SET lifecycle_state = $1, execution_outcome = $2,
    version = $3, last_event_sequence = $4,
    execution_workflow_id = $5, claim_kind = $6,
    claim_id = $7, claimed_at = $8, updated_at = $9
WHERE payment_id = $10 AND version = $11
`

type UpdatePaymentParams struct {
	LifecycleState      string
	ExecutionOutcome    string
	NextVersion         int64
	LastEventSequence   int64
	ExecutionWorkflowID *string
	ClaimKind           *string
	ClaimID             pgtype.UUID
	ClaimedAt           pgtype.Timestamptz
	UpdatedAt           pgtype.Timestamptz
	PaymentID           uuid.UUID
	ExpectedVersion     int64
}

func (q *Queries) UpdatePayment(ctx context.Context, arg UpdatePaymentParams) (int64, error) {
	result, err := q.db.Exec(ctx, updatePayment,
		arg.LifecycleState,
		arg.ExecutionOutcome,
		arg.NextVersion,
		arg.LastEventSequence,
		arg.ExecutionWorkflowID,
		arg.ClaimKind,
		arg.ClaimID,
		arg.ClaimedAt,
		arg.UpdatedAt,
		arg.PaymentID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
